import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiMobs","description":"","frontmatter":{},"headers":[],"relativePath":"modules/mobs/index.md","filePath":"modules/mobs/index.md","lastUpdated":0}`),a={name:`modules/mobs/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakimobs" tabindex="-1">EmakiMobs <a class="header-anchor" href="#emakimobs" aria-label="Permalink to “EmakiMobs”">​</a></h1><p>EmakiMobs 是自定义生物系统模块，允许服主通过 YAML 配置自定义生物属性、刷新规则、掉落表和技能行为，并深度集成 EmakiAttribute、EmakiSkills 和 EmakiItem。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.0</code></td></tr><tr><td>主命令</td><td><code>/emakimobs</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiAttribute、EmakiSkills、EmakiItem、PlaceholderAPI</td></tr><tr><td>权限节点</td><td><code>emakimobs.use</code>、<code>emakimobs.spawn</code>、<code>emakimobs.reload</code>、<code>emakimobs.debug</code>、<code>emakimobs.admin</code></td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>手动刷出生物与重载配置的命令。</td></tr><tr><td><a href="./definitions.html">生物定义</a></td><td><code>mobs/*.yml</code> 全字段说明，含组件、属性、技能、威胁表和 Boss 血条。</td></tr><tr><td><a href="./components.html">组件参考</a></td><td>ComponentMapper 支持的所有组件字段速查表。</td></tr><tr><td><a href="./spawn-rules.html">刷新规则</a></td><td><code>spawn_rules/*.yml</code> 的完整字段说明，含 <code>natural</code> 与 <code>autonomous</code> 两种类型。</td></tr><tr><td><a href="./loot-tables.html">掉落表</a></td><td><code>loot_tables/*.yml</code> 池、条目和函数的配置方法。</td></tr><tr><td><a href="./triggers.html">技能触发器</a></td><td>生物触发器列表及动作上下文变量。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>自定义生物定义</td><td>YAML 配置生物类型、属性、外观和行为，加载后立即生效。</td></tr><tr><td>类型覆写</td><td><code>id</code> 与原版 EntityType 同名时，自动对所有该类型生物应用配置。</td></tr><tr><td>两种刷新规则</td><td><code>natural</code> 拦截原版刷新事件，<code>autonomous</code> 由自己的调度器驱动（<code>interval</code> / <code>player_follow</code> / <code>day_interval</code> / <code>cron</code> 四种 trigger）。</td></tr><tr><td>掉落表系统</td><td>多池多条目设计，支持权重、概率过滤、计数函数和掠夺附魔加成。</td></tr><tr><td>EmakiItem 集成</td><td>掉落表条目使用 <code>emaki_item</code> 键直接掉落 EmakiItem 物品。</td></tr><tr><td>EmakiAttribute 集成</td><td>生物定义中的 <code>attributes</code> 节点直接写入 EA 属性。</td></tr><tr><td>技能触发器</td><td>11 种生命周期事件触发 CoreLib 动作管道。</td></tr><tr><td>威胁仇恨表</td><td>多玩家交战时按威胁值排序目标，支持权重和衰减配置。</td></tr><tr><td>Boss 血条</td><td>范围内玩家界面顶部显示生物血量，支持颜色和风格配置。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiMobs/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── mobs/                   ← 生物定义文件</span></span>
<span class="line"><span>├── loot_tables/            ← 掉落表文件</span></span>
<span class="line"><span>├── spawn_rules/            ← 刷新规则文件</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>mobs/</code> 定义生物，<code>loot_tables/</code> 定义掉落表，<code>spawn_rules/</code> 定义刷新规则。三个目录的文件只要保存在对应目录下（<code>.yml</code> 后缀），执行 <code>/emakimobs reload</code> 后即可生效。</p><h2 id="主配置" tabindex="-1">主配置 <a class="header-anchor" href="#主配置" aria-label="Permalink to “主配置”">​</a></h2><table tabindex="0"><thead><tr><th>配置键</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>当前版本</td><td>配置结构标识，不建议手动修改。</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>语言文件 ID，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>首次启动时是否释放 <code>mobs/</code>、<code>loot_tables/</code>、<code>spawn_rules/</code> 示例文件。</td></tr><tr><td><code>drain_timeout_seconds</code></td><td>int</td><td><code>30</code></td><td>重载时等待正在处理的任务完成的超时秒数。</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><ol><li>在 <code>mobs/</code> 中创建生物定义文件，指定 id、类型和组件。</li><li>在 <code>loot_tables/</code> 中创建同名掉落表文件，<code>mob_id</code> 与生物 id 对应。</li><li>在 <code>spawn_rules/</code> 中添加刷新规则，将生物与刷新条件关联。</li><li>执行 <code>/emakimobs reload</code> 或重启服务器使配置生效。</li><li>使用 <code>/emakimobs spawn &lt;mob_id&gt;</code> 在当前位置测试刷出效果。</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiAttribute</td><td>生物定义的 <code>attributes</code> 节点直接写入 EA 属性值。</td></tr><tr><td>EmakiSkills</td><td>生物定义的 <code>skills</code> 节点在触发器事件发生时调用 CoreLib 动作管道。</td></tr><tr><td>EmakiItem</td><td>掉落表条目用 <code>emaki_item</code> 键指定 EmakiItem 物品 ID，掉落自定义物品。</td></tr><tr><td>EmakiCoreLib</td><td>依赖 CoreLib 的动作管道系统执行技能动作，依赖其生命周期基础设施。</td></tr></tbody></table>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};